const OJS_NODE = 'Read Operative Job Sheet';

function rowsFrom(name) {
  try { return $(name).all().map((i) => i.json || {}); } catch (e) { return []; }
}

function norm(v) {
  return String(v ?? '').trim().toLowerCase().replace(/\s+/g, ' ');
}

function normCorf(v) {
  return String(v ?? '').trim().toUpperCase().replace(/\s+/g, '');
}

function corfFromQ11(addr) {
  const s = String(addr ?? '').trim();
  const m = s.match(/-(\d+\/\d+)\s*$/);
  return m ? m[1] : '';
}

function corfFromRow(row) {
  const direct = normCorf(row.CORF ?? row.corf);
  if (direct) return direct;
  return normCorf(corfFromQ11(row['Q1.1 Address']));
}

function isHeader(row) {
  return /^smartform name$/i.test(String(row['SmartForm Name'] ?? '').trim());
}

function isBcc(name) {
  return /:\s*BCC\s+Respon(?:se|sive)\s+Repairs\b/i.test(String(name ?? '').trim());
}

function isNoOrEmpty(v) {
  const s = String(v ?? '').trim();
  if (!s) return true;
  const low = s.toLowerCase();
  return low === 'no' || low === 'n' || low === 'false' || low === '0';
}

function normJobStatus(v) {
  const s = norm(v);
  if (!s) return '';
  if (s.startsWith('incomp') || s === 'incomplete') return 'incomplete';
  if (s.startsWith('comp') || s === 'complete' || s === 'completed') return 'completed';
  return s;
}

function jobStatusValue(row) {
  return row['Job Status'] ?? row.job_status ?? '';
}

function isJobStatusComplete(row) {
  return normJobStatus(jobStatusValue(row)) === 'completed';
}

function isReadyHandoverNo(row) {
  return isNoOrEmpty(row['Ready To Hand over'] ?? row['Ready to handover']);
}

function isHandoverTaskNotCreated(row) {
  return isNoOrEmpty(row['Hand Over Task Created'] ?? row['Handover Task Created']);
}

const rows = rowsFrom(OJS_NODE).filter((r) => !isHeader(r));
const queue = [];
let skippedNotBcc = 0;
let skippedNotCompleted = 0;
let skippedReadyHandover = 0;
let skippedTaskDone = 0;
let skippedNoCorf = 0;

for (const row of rows) {
  const name = String(row['SmartForm Name'] ?? '').trim();
  if (!isBcc(name)) { skippedNotBcc++; continue; }
  if (!isJobStatusComplete(row)) { skippedNotCompleted++; continue; }
  if (!isReadyHandoverNo(row)) { skippedReadyHandover++; continue; }
  if (!isHandoverTaskNotCreated(row)) { skippedTaskDone++; continue; }

  const corfRaw = String(row.CORF ?? corfFromRow(row) ?? '').trim();
  const corf = normCorf(corfRaw);
  if (!corf) { skippedNoCorf++; continue; }

  queue.push({
    row_number: row.row_number ?? row.rowNumber ?? null,
    client_order_reference: corfRaw || corf,
    corf,
    smart_form_name: name,
    job_status: String(jobStatusValue(row)).trim(),
    smartform_status: String(row.Status ?? '').trim(),
    ready_to_handover: String(row['Ready To Hand over'] ?? row['Ready to handover'] ?? '').trim() || null,
    hand_over_task_created: String(row['Hand Over Task Created'] ?? '').trim() || null,
    address: String(row['Q1.1 Address'] ?? row['Job Header'] ?? '').trim(),
    action: 'create_handover_task',
  });
}

const stats = {
  ojs_rows: rows.length,
  eligible: queue.length,
  queued: queue.length,
  skipped_not_bcc: skippedNotBcc,
  skipped_not_complete: skippedNotCompleted,
  skipped_ready_handover: skippedReadyHandover,
  skipped_task_done: skippedTaskDone,
  skipped_no_corf: skippedNoCorf,
};

const sd = $getWorkflowStaticData('global');
sd.handoverTaskLogs = [];
sd.handoverTaskStats = stats;

if (!queue.length) {
  return [{
    json: {
      _workflow_only: true,
      _no_jobs: true,
      message: `No eligible OJS rows for handover task (eligible=${queue.length})`,
      ...stats,
    },
  }];
}

return queue.map((row, i) => ({
  json: { ...row, _job_index: i + 1, _job_total: queue.length, ...stats },
}));

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.works_id === undefined && body.results === undefined) {
    body = body.body;
  }
  return body || {};
}

const resp = $input.first().json || {};
const resolve = bodyFrom(resp);
const job = $('Loop handover tasks').item.json || {};

return [{
  json: {
    ...job,
    works_id: String(resolve.works_id || '').trim(),
    resolve_found: Boolean(resolve.found),
    resolve_address: resolve.address || '',
    resolve_error: resolve.error || null,
  },
}];

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.success === undefined && body.works_id === undefined) {
    body = body.body;
  }
  return body || {};
}

const job = $('Loop handover tasks').item.json || {};
const parsed = $('Parse resolve response').first().json || {};
const raw = $input.first().json || {};
const task = bodyFrom(raw);
const rn = job.row_number;
const taskOk = task.success === true;
const shouldMark = taskOk && rn !== null && rn !== undefined && rn !== '';

if (!shouldMark) {
  return [{
    json: {
      _skip_sheet: true,
      row_number: rn,
      client_order_reference: job.client_order_reference || '',
      works_id: parsed.works_id || '',
      smart_form_name: job.smart_form_name || '',
      task_success: taskOk,
      task_already_exists: task.already_exists === true,
      task_message: task.message || '',
    },
  }];
}

const now = new Date();
const taskCreatedDate = `${String(now.getDate()).padStart(2, '0')}/${String(now.getMonth() + 1).padStart(2, '0')}/${now.getFullYear()}`;

return [{
  json: {
    _skip_sheet: false,
    row_number: rn,
    'Hand Over Task Created': taskCreatedDate,
    client_order_reference: job.client_order_reference || '',
    works_id: parsed.works_id || '',
    smart_form_name: job.smart_form_name || '',
    task_success: true,
    task_already_exists: task.already_exists === true,
    task_message: task.message || '',
  },
}];

function bodyFrom(resp) {
  let body = resp.body ?? resp.data ?? resp;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) { body = {}; }
  }
  if (body && body.body && body.success === undefined && body.works_id === undefined) {
    body = body.body;
  }
  return body || {};
}

const sd = $getWorkflowStaticData('global');
if (!Array.isArray(sd.handoverTaskLogs)) sd.handoverTaskLogs = [];

const job = $('Loop handover tasks').item.json || {};
const parsed = $('Parse resolve response').first().json || {};

let task = {};
let step = 'resolve_failed';
try {
  const raw = $('Create handover task').first().json || {};
  task = bodyFrom(raw);
  if (task && (task.success !== undefined || task.works_id)) step = 'task_created';
} catch (e) {}

let sheetMarked = false;
let handOverTaskCreated = null;
try {
  const prep = $('Prepare sheet mark').first().json || {};
  if (prep._skip_sheet !== true) {
    handOverTaskCreated = prep['Hand Over Task Created'] || null;
    try {
      $('Update Hand Over Task Created').first();
      sheetMarked = true;
    } catch (e2) {
      sheetMarked = Boolean(handOverTaskCreated);
    }
  }
} catch (e) {}

const entry = {
  step,
  job_index: job._job_index || null,
  job_total: job._job_total || null,
  row_number: job.row_number || null,
  client_order_reference: job.client_order_reference || '',
  works_id: parsed.works_id || job.works_id || '',
  smart_form_name: job.smart_form_name || '',
  resolve_found: Boolean(parsed.resolve_found),
  resolve_error: parsed.resolve_error || null,
  task_success: task.success === true,
  task_already_exists: task.already_exists === true,
  complete_by_date: task.complete_by_date || null,
  hand_over_task_created: handOverTaskCreated,
  sheet_marked: sheetMarked,
  message: task.message || parsed.resolve_error || 'skipped — works_id not found',
  logged_at: new Date().toISOString(),
};

sd.handoverTaskLogs.push(entry);
return [{ json: entry }];

const sd = $getWorkflowStaticData('global');
const logs = Array.isArray(sd.handoverTaskLogs) ? sd.handoverTaskLogs : [];
const stats = sd.handoverTaskStats || {};

const created = logs.filter((l) => l.step === 'task_created' && l.task_success && !l.task_already_exists).length;
const skippedExists = logs.filter((l) => l.task_already_exists).length;
const sheetMarked = logs.filter((l) => l.sheet_marked).length;
const resolveFailed = logs.filter((l) => l.step === 'resolve_failed').length;
const taskFailed = logs.filter((l) => l.step === 'task_created' && !l.task_success).length;

const lines = logs.map((l) => {
  const corf = l.client_order_reference || '-';
  const wid = l.works_id || '-';
  if (l.step === 'resolve_failed') return `SKIP resolve corf=${corf} — ${l.message}`;
  if (l.task_already_exists) return `SKIP exists corf=${corf} works_id=${wid} sheet=${l.hand_over_task_created || 'not marked'}`;
  return `${l.task_success ? 'OK' : 'FAIL'} corf=${corf} works_id=${wid} sheet=${l.hand_over_task_created || '-'} ${l.message || ''}`;
});

return [{
  json: {
    _workflow_only: true,
    workflow: 'stage7_handover_task',
    finished_at: new Date().toISOString(),
    stats,
    processed: logs.length,
    created,
    sheet_marked: sheetMarked,
    skipped_existing: skippedExists,
    resolve_failed: resolveFailed,
    task_failed: taskFailed,
    log_lines: lines,
    message: `Handover task run done — created ${created}, sheet_marked=${sheetMarked}, skipped_existing=${skippedExists}, failed=${taskFailed + resolveFailed}`,
  },
}];
